// ---------------- Code: Extract Headlines ----------------
const items = $("RSS: Crypto News").all();
const seen = new Set();
const headlines = [];
for (const it of items) {
  const t = typeof it.json.title === "string" ? it.json.title.trim() : "";
  if (!t || seen.has(t)) continue;
  seen.add(t);
  headlines.push(t.replace(/\s+/g, " "));
}
return [{json:{headlines:headlines.slice(-25)}}];

// ---------------- Code: Build Universe ----------------
const ws = $getWorkflowStaticData("global");
const cfg = ws.config || {};
const _tickersRaw = $("HTTP: Binance 24h Tickers").all().map(i => i.json);
const tickers = (_tickersRaw.length === 1 && Array.isArray(_tickersRaw[0])) ? _tickersRaw[0] : _tickersRaw;
const stableBases = new Set(["USDC","BUSD","TUSD","DAI","USDP","USDD","FDUSD","EUR","GBP","AUD","RUB","TRY","BVND","UAH"]);
const ranked = tickers
  .filter(t => t.symbol && t.symbol.endsWith("USDT"))
  .map(t => ({symbol:t.symbol, quoteVolume:parseFloat(t.quoteVolume)||0, lastPrice:parseFloat(t.lastPrice)||0, priceChangePercent:parseFloat(t.priceChangePercent)||0}))
  .filter(t => !stableBases.has(t.symbol.slice(0,-4)))
  .sort((a,b) => b.quoteVolume - a.quoteVolume);
const cap = cfg.MAX_SYMBOLS_PER_RUN || 12;
const wl = Array.isArray(cfg.WATCHLIST) ? cfg.WATCHLIST.filter(w => w.enabled).map(w => w.symbol) : [];
const mode = cfg.MODE || "embedded";
let uni;
if (mode === "embedded" && wl.length) {
  const bySym = new Map(ranked.map(u => [u.symbol, u]));
  uni = wl.slice(0, cap).map(symbol => bySym.get(symbol) || {symbol, quoteVolume:0, lastPrice:0, priceChangePercent:0});
} else {
  uni = ranked.slice(0, cap);
}
return uni.map((u,i) => ({json:{...u, idx:i, runId:ws.runId}}));

// ---------------- Code: Flush Log Items ----------------
const ws = $getWorkflowStaticData("global");
const res = ws.results || [];
const rows = res.map(r => {
  const rr = {...r};
  rr.created_at = new Date(r.ts).toISOString();
  return rr;
});
ws.lastRun = {count:rows.length, ts:Date.now()};
return [{json:{rows:rows, count:rows.length}}];

// ---------------- Code: Digest Builder ----------------
const ws = $getWorkflowStaticData("global");
const cfg = ws.config||{};
const res = ws.results||[];
const tradables = res.filter(r=>["LONG","SHORT"].includes(r.decision));
const lines = tradables.slice(0,6).map(r=>"\u2022 "+r.decision+" "+r.symbol+" str "+r.signal_strength.toFixed(2)+" conf "+r.confidence.toFixed(2));
const txt = "<b>Jev Ensemble v2 \u2014 Hourly Scan Digest</b>\n"
  +"Scanned: <b>"+res.length+"</b> USDT perps | Tradables: <b>"+tradables.length+"</b> | Run id: "+ws.runId+"\n\n"
  +(lines.length?lines.join("\n"):"No actionable signals this hour.")
  +(tradables.length>6?"\n\u2026":"");
return [{json:{sendDigest:!!cfg.SEND_DIGEST, digestText:txt, tradable_count:tradables.length, scanned_count:res.length}}];

// ---------------- Code: Collapse 1h ----------------
// HTTP node splits the klines array into one item per candle; collapse back to one item
// so the next request fires once per symbol.
const raw = $input.all().map(i => i.json);
const klines = (raw.length === 1 && Array.isArray(raw[0]) && Array.isArray(raw[0][0])) ? raw[0] : raw;
const symbol = $("Split In Batches: Symbols").item.json.symbol;
return [{json:{symbol:symbol, klines:klines}}];

// ---------------- Code: Collapse 4h ----------------
const raw = $input.all().map(i => i.json);
const klines = (raw.length === 1 && Array.isArray(raw[0]) && Array.isArray(raw[0][0])) ? raw[0] : raw;
const symbol = $("Split In Batches: Symbols").item.json.symbol;
return [{json:{symbol:symbol, klines:klines}}];

// ---------------- Code: Fetch Symbol Bundle ----------------
const item = $("Split In Batches: Symbols").item.json;
const k1 = $("Code: Collapse 1h").first().json.klines;
const k4 = $("Code: Collapse 4h").first().json.klines;
const pi = $("HTTP: Premium Index").first().json;
const oi = $("HTTP: OI History 1h").all().map(i => i.json);
return [{json:{
  symbol:item.symbol, quoteVolume:item.quoteVolume, lastPrice:item.lastPrice,
  priceChangePercent:item.priceChangePercent, idx:item.idx, runId:item.runId,
  klines1h:k1, klines4h:k4,
  fundingRate: pi.lastFundingRate ? parseFloat(pi.lastFundingRate) : null,
  nextFundingTime: pi.nextFundingTime || null,
  markPrice: pi.markPrice ? parseFloat(pi.markPrice) : null,
  oi: oi
}}];

// ---------------- Code: TA Engine + Crowding ----------------
const src = $input.first().json;
const H = src.klines1h, D = src.klines4h;
function closes(k){ return k.map(x=>Number(x[4])); }
function highs(k){ return k.map(x=>Number(x[2])); }
function lows(k){ return k.map(x=>Number(x[3])); }
function vols(k){ return k.map(x=>Number(x[5])); }
function ema(v,p){ const k=2/(p+1); let e=v.slice(0,p).reduce((a,b)=>a+b,0)/p; const o=new Array(p-1).fill(null); o.push(e); for(let i=p;i<v.length;i++){e=v[i]*k+e*(1-k);o.push(e);} return o; }
function rsi(c,p=14){ let g=0,l=0; for(let i=1;i<=p;i++){const d=c[i]-c[i-1]; if(d>0)g+=d; else l-=d;} let ag=g/p, al=l/p; for(let i=p+1;i<c.length;i++){const d=c[i]-c[i-1]; ag=(ag*(p-1)+Math.max(d,0))/p; al=(al*(p-1)+Math.max(-d,0))/p;} return al===0?100:100-100/(1+ag/al); }
function tr(h,l,c,i){ return Math.max(h[i]-l[i], Math.abs(h[i]-c[i-1]), Math.abs(l[i]-c[i-1])); }
function atrPct(h,l,c,p=14){ let a=0; for(let i=1;i<=p;i++) a+=tr(h,l,c,i); a/=p; for(let i=p+1;i<h.length;i++) a=(a*(p-1)+tr(h,l,c,i))/p; return (a/c[c.length-1])*100; }
function bb(c,p=20){ const w=c.slice(-p); const m=w.reduce((a,b)=>a+b,0)/p; const v=w.reduce((a,b)=>a+(b-m)**2,0)/p; const sd=Math.sqrt(v||1e-12); const pos=(c[c.length-1]-m)/(2*sd); return {pos:pos, width:(2*sd)/m}; }
const last=a=>a[a.length-1];
function macdHist(c,f=12,s=26,sp=9){ const e12=ema(c,f), e26=ema(c,s); const ml=c.map((_,i)=>(e12[i]!=null&&e26[i]!=null)?e12[i]-e26[i]:null).filter(v=>v!=null); const sg=ema(ml,sp); return (ml.length&&sg.length)?ml[ml.length-1]-sg[sg.length-1]:0; }
function volAvg(c,v,p=20){ const w=v.slice(-p); const avg=w.reduce((a,b)=>a+b,0)/p; return avg?v[c.length-1]/avg:1; }
function regime(c,h,l,p=14){ const r=rsi(c,p); const e=ema(c,12); const s=ema(c,26); const el=last(e), sl=last(s); return (el>sl && r>55)?"trending_up":(el<sl && r<45)?"trending_down":"ranging"; }
function takerApprox(c,o,v,p=20){ let b=0,t=0; for(let i=c.length-p;i<c.length;i++){t+=v[i]; if(c[i]>=o[i])b+=v[i];} return t?(b/t):0.5; }
const c1=closes(H), o1=H.map(x=>Number(x[1])), v1=vols(H), h1=highs(H), l1=lows(H);
const c4=closes(D), o4=D.map(x=>Number(x[1])), v4=vols(D), h4=highs(D), l4=lows(D);
const b1=bb(c1), b4=bb(c4);
const m1={
  rsi_14:+rsi(c1).toFixed(2), ema12:+last(ema(c1,12)).toFixed(2), ema26:+last(ema(c1,26)).toFixed(2),
  macd_hist:+macdHist(c1).toFixed(2), atr_pct:+atrPct(h1,l1,c1).toFixed(2),
  bb_pos:+b1.pos.toFixed(3), bb_width:+b1.width.toFixed(4),
  vol_vs_avg:+volAvg(c1,v1).toFixed(2), taker_buy_approx:+takerApprox(c1,o1,v1).toFixed(3), regime:regime(c1,h1,l1)
};
const m4={
  rsi_14:+rsi(c4).toFixed(2), ema12:+last(ema(c4,12)).toFixed(2), ema26:+last(ema(c4,26)).toFixed(2),
  macd_hist:+macdHist(c4).toFixed(2), atr_pct:+atrPct(h4,l4,c4).toFixed(2),
  bb_pos:+b4.pos.toFixed(3), bb_width:+b4.width.toFixed(4),
  vol_vs_avg:+volAvg(c4,v4).toFixed(2), taker_buy_approx:+takerApprox(c4,o4,v4).toFixed(3), regime:regime(c4,h4,l4)
};
const conf = (m1.regime===m4.regime && m1.regime!=="ranging")?(m1.regime==="trending_up"?"aligned_bullish":"aligned_bearish"):"mixed";
const cfg = ($getWorkflowStaticData("global")).config||{};
const squeeze = m1.bb_width < (cfg.BB_SQUEEZE_WIDTH||0.03);
// --- crowding gate: fade the crowded side ---------------------------------
const fr = src.fundingRate;
const fundingAnnual = (fr!=null)?fr*3*365:null;
let oiChangePct=null;
try{
  const oi = src.oi.map(r=>({ts:Number(r.timestamp||r.openInterestTimestamp||0), oi:parseFloat(r.sumOpenInterest ?? r.openInterest)})).filter(r=>!isNaN(r.oi)&&r.oi>0);
  if (oi.length>=2){ oi.sort((a,b)=>a.ts-b.ts); const pv=oi[oi.length-2].oi, cu=oi[oi.length-1].oi; oiChangePct=(cu-pv)/pv*100; }
}catch(e){ oiChangePct=null; }
let blockedReason="", allowedSide="both";
if (fundingAnnual!=null && oiChangePct!=null){
  if (fundingAnnual > (cfg.FUNDING_BLOCK_LONG_ANNUAL||0.30) && oiChangePct > (cfg.OI_BLOCK_PCT||3.0)){ blockedReason="crowding_long_blocked"; allowedSide="short"; }
  else if (fundingAnnual < (cfg.FUNDING_BLOCK_SHORT_ANNUAL||-0.10) && oiChangePct < -(cfg.OI_BLOCK_PCT||3.0)){ blockedReason="crowding_short_blocked"; allowedSide="long"; }
}
return [{json:{...src, metrics1h:m1, metrics4h:m4, regime1h:m1.regime, regime4h:m4.regime, confluence:conf, squeeze:squeeze, fundingAnnual:fundingAnnual, oiChangePct:oiChangePct, takerBuyApprox:m1.taker_buy_approx, blockedReason:blockedReason, allowedSide:allowedSide}}];

// ---------------- Code: Build Jev Payload ----------------
const src = $input.first().json;
const ws = $getWorkflowStaticData("global");
const cfg = ws.config||{};
const headlines = $("Code: Extract Headlines").first().json.headlines||[];
const m1=src.metrics1h, m4=src.metrics4h;
const candles1h = src.klines1h.slice(-20).map(k=>({t:k[0],o:+k[1],h:+k[2],l:+k[3],c:+k[4],v:+k[5]}));
const candles4h = src.klines4h.slice(-20).map(k=>({t:k[0],o:+k[1],h:+k[2],l:+k[3],c:+k[4],v:+k[5]}));
const state = {
  market:{
    symbol:src.symbol, timeframe:"1h",
    candles_recent:candles1h, candles_4h_recent:candles4h,
    indicators:{
      rsi_14:m1.rsi_14, ema_fast:m1.ema12, ema_slow:m1.ema26, macd_hist:m1.macd_hist,
      atr_pct:m1.atr_pct, bb_pos:m1.bb_pos, bb_width:m1.bb_width, vol_vs_avg:m1.vol_vs_avg,
      rsi_4h:m4.rsi_14, ema12_4h:m4.ema12, ema26_4h:m4.ema26, macd_hist_4h:m4.macd_hist,
      confluence_4h:src.confluence, regime_1h:src.regime1h, regime_4h:src.regime4h, squeeze:src.squeeze
    },
    order_flow:{
      funding_rate_8h:src.fundingRate, funding_annualized:src.fundingAnnual,
      taker_buy_ratio_approx:src.takerBuyApprox, oi_change_pct_1h:src.oiChangePct
    },
    regime:src.regime1h, allowed_side:src.allowedSide
  },
  news:{headlines_last_24h:headlines.slice(-25)}
};
const questions = {
  direction:{
    type:"choice",
    instructions:{
      question:"Based on `market.indicators` across BOTH timeframes (1h and 4h), the recent closes in `market.candles_recent`, `market.order_flow` (funding, OI change, approximate taker ratio), and `market.news`, what is the likely direction of `market.symbol` over the next few `market.timeframe` candles?",
      focus:"Weigh technical indicators and price action most heavily; order flow is secondary confirmation; news is tertiary. If `market.indicators.confluence_4h` disagrees with the 1h picture, lean toward neutral."
    },
    criteria:{
      bullish:{what:"Evidence supports upward price movement",signals:["Fast EMA above slow EMA on 1h and ideally 4h","RSI 50-70 with rising closes","Positive MACD histogram"]},
      bearish:{what:"Evidence supports downward price movement",signals:["Fast EMA below slow EMA on 1h and ideally 4h","RSI 30-50 with falling closes","Negative MACD histogram"]},
      neutral:{what:"Mixed or conflicting evidence, likely range-bound",not_for:"A weak trend still counts as directional if indicators agree",signals:["Indicators contradict each other across timeframes","Price compressed inside Bollinger bands"]}
    }
  },
  trend_strength:{
    type:"score",
    instructions:{question:"How strong is the current directional momentum in `market`?",focus:"Confluence of indicators and volume, not direction."},
    criteria:[
      {what:"No momentum",signals:["Flat indicators","Low volume","Range-bound"]},
      {what:"Weak momentum",signals:["Some indicators agree","Volume below average"]},
      {what:"Moderate momentum",signals:["Most indicators agree","Average volume"]},
      {what:"Strong momentum",signals:["All indicators agree","Volume expanding","Clean trend structure"]}
    ]
  },
  breakout_confirmed:{type:"noul",instructions:"Do the closes in `market.candles_recent` and `market.indicators` confirm a breakout from the prior range?"},
  news_supports_direction:{type:"noul",instructions:"Do the headlines in `news.headlines_last_24h` support the direction implied by `market.indicators`?",criteria:{true:"Headlines are directionally consistent with the technical picture",false:"Headlines are contradictory, irrelevant, or missing"}},
  risk_off_environment:{type:"noul",instructions:"Do `news.headlines_last_24h` or `market.regime` indicate a risk-off environment (panic, liquidations, macro fear) that could invalidate technical signals?"},
  volatility_dangerous:{type:"noul",instructions:"Is `market.indicators.atr_pct` high enough to threaten stop-loss-based positions?"}
};
return [{json:{symbol:src.symbol, timeframe:"1h", idx:src.idx, runId:src.runId, allowedSide:src.allowedSide, regime1h:src.regime1h, regime4h:src.regime4h, confluence:src.confluence, squeeze:src.squeeze, metrics1h:m1, metrics4h:m4, fundingAnnual:src.fundingAnnual, oiChangePct:src.oiChangePct, blockedReason:src.blockedReason, nextFunding:src.nextFundingTime, payload:{state:state, questions:questions, model:cfg.MODEL||"typesafe/jev-1.13"}}}];

