// ---------------- Code: Combine to Signal ----------------
const resp = $input.first().json;
const meta = $("Code: Build Jev Payload").item.json;
const inp = {...meta, ...resp};
const answers = resp.answers;
if (!answers || Object.keys(answers).length===0) { return [{json:inp}]; }
const d = answers.direction||{}; const probs = d.probabilities||{};
const bull = probs.bullish||0, bear = probs.bearish||0, neu = probs.neutral||0;
const conf = d.confidence||0; const net = bull-bear;
const ts = (answers.trend_strength && answers.trend_strength.score!==undefined)?answers.trend_strength.score:0;
const noul = k => ((answers[k] && answers[k].noul!==undefined)?answers[k].noul:0);
const ws = $getWorkflowStaticData("global"); const cfg = ws.config||{};
let s = (cfg.WEIGHT_NET||0.40)*net
      + (cfg.WEIGHT_TREND||0.15)*(ts/3)*(net>0?1:-1)
      + (cfg.WEIGHT_BREAKOUT||0.15)*(noul("breakout_confirmed")-0.5)*2
      + (cfg.WEIGHT_NEWS||0.15)*(noul("news_supports_direction")-0.5)*2
      + (cfg.WEIGHT_RISKOFF||-0.10)*noul("risk_off_environment")
      + (cfg.WEIGHT_VOL||-0.10)*noul("volatility_dangerous");
s = Math.max(-1, Math.min(1, s));
let decision;
const CG = cfg.CONFIDENCE_GATE||0.60, SF = cfg.STRENGTH_FLOOR||1.5, SL = cfg.SIGNAL_LONG||0.25, SS = cfg.SIGNAL_SHORT||-0.25;
if (conf < CG) decision = "NO_TRADE_LOW_CONFIDENCE";
else if (ts < SF) decision = "NO_TRADE_WEAK_TREND";
else if (s > SL) decision = "LONG";
else if (s < SS) decision = "SHORT";
else decision = "FLAT";
// respect crowding gate: never take the blocked side
if (inp.allowedSide==="long" && decision==="SHORT") decision="FLAT";
if (inp.allowedSide==="short" && decision==="LONG") decision="FLAT";
if (inp.allowedSide==="none") decision = "NO_TRADE_CROWDING";
const msg = "Jev: "+decision+" "+inp.symbol+" (1h, 4h "+inp.confluence+") | Conf "+conf.toFixed(2)+" | Str "+s.toFixed(2)+" | Trend "+ts+" | P(bull)"+bull.toFixed(2)+" P(bear)"+bear.toFixed(2)+" P(neu)"+neu.toFixed(2)+" | Fund "+((inp.fundingAnnual||0)*100).toFixed(1)+"%/yr OI "+((inp.oiChangePct||0)>=0?"+":"")+(inp.oiChangePct||0).toFixed(2)+"%";
return [{json:{
  symbol:inp.symbol, timeframe:inp.timeframe||"1h", runId:inp.runId||null, idx:inp.idx,
  decision:decision, direction_choice:d.choice||null, probabilities:probs, confidence:+conf.toFixed(4),
  signal_strength:+s.toFixed(4), trend_strength:ts,
  breakout_confirmed:+noul("breakout_confirmed").toFixed(4), news_supports:+noul("news_supports_direction").toFixed(4),
  risk_off:+noul("risk_off_environment").toFixed(4), volatility_dangerous:+noul("volatility_dangerous").toFixed(4),
  allowedSide:inp.allowedSide, blockedReason:inp.blockedReason||"", regime1h:inp.regime1h, regime4h:inp.regime4h,
  confluence:inp.confluence, squeeze:inp.squeeze, fundingAnnual:inp.fundingAnnual, oiChangePct:inp.oiChangePct,
  takerBuyApprox:inp.takerBuyApprox, nextFunding:inp.nextFunding, message:msg, raw_answers:answers
}}];

// ---------------- Code: Cooldown Check ----------------
const ws = $getWorkflowStaticData("global");
if (!ws.symbolAlert) ws.symbolAlert = {};
const cfg = ws.config||{};
const sym = $input.first().json.symbol;
const last = ws.symbolAlert[sym] || 0;
const hours = cfg.COOLDOWN_HOURS||4;
const now = Date.now();
const allowed = (now-last) > hours*3600*1000;
return [{json:{...$input.first().json, alert_allowed:allowed, last_alert_ago_hours:+((now-last)/3600000).toFixed(2)}}];

// ---------------- Code: Telegram Message ----------------
const r = $input.first().json;
const esc = s => String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
const d = r.decision; const e = d==="LONG"?"\ud83d\udfe2":d==="SHORT"?"\ud83d\udd34":"\u26aa";
const nf = r.nextFunding ? new Date(r.nextFunding).toISOString().slice(0,16) : "n/a";
const txt = "<b>Jev Ensemble v2 \u2014 Signal Alert</b>\n\n"
  +"<b>"+e+" "+esc(d)+"  "+esc(r.symbol)+"</b>  <i>("+esc(r.timeframe||"1h")+", 4h "+esc(r.confluence||"?")+")</i>\n"
  +"Confidence: <b>"+(r.confidence||0).toFixed(2)+"</b> | Signal strength: "+(r.signal_strength||0).toFixed(2)+" | Trend: "+(r.trend_strength||0)+"/3\n"
  +"P(bull) "+(r.probabilities.bullish||0).toFixed(2)+"  P(bear) "+(r.probabilities.bearish||0).toFixed(2)+"  P(neutral) "+(r.probabilities.neutral||0).toFixed(2)+"\n\n"
  +"Regime 1h: "+esc(r.regime1h||"?")+" | Regime 4h: "+esc(r.regime4h||"?")+(r.squeeze?" | BB SQUEEZE":"")+"\n"
  +"RSI14: "+esc((r.metrics1h&&r.metrics1h.rsi_14)||"?")+" | MACD: "+esc((r.metrics1h&&r.metrics1h.macd_hist)||"?")+" | Vol vs avg: "+esc((r.metrics1h&&r.metrics1h.vol_vs_avg)||"?")+"x | Taker buy~: "+esc((r.takerBuyApprox||0).toFixed(2))+"\n"
  +"Funding (annualized): "+((r.fundingAnnual||0)*100).toFixed(1)+"% | OI 1h: "+((r.oiChangePct||0)>=0?"+":"")+(r.oiChangePct||0).toFixed(2)+"%\n"
  +"Crowding gate: "+esc(r.blockedReason||"open")+" | Next funding: "+nf+"\n\n"
  +"<i>Paper-trade first. Logged to jev_signals; tune gates in Config node.</i>";
return [{json:{...r, telegramText:txt}}];

// ---------------- Code: Mark Cooled ----------------
const ws = $getWorkflowStaticData("global");
if (!ws.symbolAlert) ws.symbolAlert = {};
ws.symbolAlert[$input.first().json.symbol] = Date.now();
return $input.all();

// ---------------- Code: Accumulate Result ----------------
const ws = $getWorkflowStaticData("global");
if (!Array.isArray(ws.results)) ws.results = [];
const r = $input.first().json;
ws.results.push({
  symbol:r.symbol, ts:Date.now(), runId:r.runId||ws.runId, idx:r.idx,
  decision:r.decision, allowed_side:r.allowedSide, blocked_reason:r.blockedReason||"",
  confidence:r.confidence||0, signal_strength:r.signal_strength||0, trend_strength:r.trend_strength||0,
  probabilities:r.probabilities||{}, breakout_confirmed:r.breakout_confirmed||0,
  news_supports:r.news_supports||0, risk_off:r.risk_off||0, volatility_dangerous:r.volatility_dangerous||0,
  regime1h:r.regime1h, regime4h:r.regime4h, confluence:r.confluence, squeeze:!!r.squeeze,
  fundingAnnual:r.fundingAnnual, oiChangePct:r.oiChangePct, takerBuyApprox:r.takerBuyApprox,
  cooldown_skipped:!(r.alert_allowed!==false), alert_sent:!!r.telegramText, raw_answers:r.raw_answers||null
});
return [{json:{ok:true, symbol:r.symbol, decision:r.decision}}];

// ---------------- Code: Crowd-Skip Record ----------------
const src = $input.first().json;
const runId = ($getWorkflowStaticData("global")).runId || null;
return [{json:{
  symbol:src.symbol, timeframe:"1h", runId:runId, idx:src.idx,
  decision:"NO_TRADE_CROWDING", allowedSide:src.allowedSide, blockedReason:src.blockedReason,
  probabilities:{}, confidence:0, signal_strength:0, trend_strength:0, breakout_confirmed:0,
  news_supports:0, risk_off:0, volatility_dangerous:0,
  regime1h:src.regime1h, regime4h:src.regime4h, confluence:src.confluence, squeeze:src.squeeze,
  fundingAnnual:src.fundingAnnual, oiChangePct:src.oiChangePct, takerBuyApprox:src.takerBuyApprox,
  raw_answers:null, alert_allowed:true, message:"Jev: NO_TRADE_CROWDING "+src.symbol+" ("+(src.blockedReason||"crowding")+")"
}}];
